/// Match the language part of Windows/Android locale tags, then use English.
Locale resolveAppLocale(List<Locale>? preferred, Iterable<Locale> supported) {
  final available = supported.toList(growable: false);
  for (final candidate in preferred ?? const <Locale>[]) {
    for (final locale in available) {
      if (locale.languageCode == candidate.languageCode) return locale;
    }
  }
  return available.where((v) => v.languageCode == 'en').firstOrNull ??
      const Locale('en');
}

extension AppTranslations on BuildContext {
  String tr(String source, {Map<String, Object?> values = const {}}) =>
      AppStrings(Localizations.localeOf(this))
          .translate(source, values: values);
}

class AppStrings {
  const AppStrings(this.locale);
  final Locale locale;

  String translate(String source, {Map<String, Object?> values = const {}}) {
    var result = source;
    final index = _languages.indexOf(locale.languageCode);
    if (index >= 0) {
      final translations = _catalog[source];
      if (translations != null) {
        result = translations[index];
      } else {
        // Also handles existing status helpers that have already interpolated
        // a provider name or count. Matching is anchored, never a substring edit.
        for (final template in _templates) {
          final match = template.pattern.firstMatch(source);
          if (match == null) continue;
          result = _catalog[template.source]![index];
          for (var i = 0; i < template.names.length; i++) {
            result = result.replaceAll(
              '{${template.names[i]}}',
              match.group(i + 1)!,
            );
          }
          break;
        }
      }
    }
    for (final entry in values.entries) {
      result = result.replaceAll('{${entry.key}}', '${entry.value ?? ''}');
    }
    return result;
  }
}

const _languages = ['en', 'kk', 'de', 'fr', 'es', 'pt', 'tr', 'zh', 'ar'];

final Map<String, List<String>> _catalog = {
  for (final row in _rows.trim().split('\n'))
    row.split('|').first: row.split('|').skip(1).toList(growable: false),
};

final _templates = [
  for (final key in _catalog.keys)
    if (key.contains('{')) _TranslationTemplate(key),
];

class _TranslationTemplate {
  _TranslationTemplate(this.source) {
    final token = RegExp(r'\{(\w+)\}');
    final buffer = StringBuffer('^');
    var cursor = 0;
    for (final match in token.allMatches(source)) {
      buffer.write(RegExp.escape(source.substring(cursor, match.start)));
      buffer.write('(.+?)');
      names.add(match.group(1)!);
      cursor = match.end;
    }
    buffer.write(RegExp.escape(source.substring(cursor)));
    buffer.write(r'$');
    pattern = RegExp(buffer.toString());
  }
  final String source;
  final names = <String>[];
  late final RegExp pattern;
}

